// Automatisch erzeugt von scripts/cache-team-logos.mjs --embed --write. Nicht von Hand bearbeiten.
// file://-Fallback für den Social-Video-Renderer: stellt window.SOCIAL_VIDEO_ASSETS (Team-Logos, VfB-Logo,
// Spatz) als data:-URIs bereit. Grund: unter file:// behandelt Chrome jede lokale Datei als eigene fremde
// Herkunft — auch ein per <img src="assets/…"> von derselben Festplatte geladenes Bild verunreinigt das
// Canvas (captureStream()/toDataURL() schlagen danach fehl). data:-URIs haben dieses Problem nicht. Der
// Renderer liest ausschließlich aus dieser Quelle; fehlt ein Schlüssel, greift der Initialen-Fallback. Die
// Story-VORSCHAU im Dashboard ist davon unberührt und nutzt weiter die Dateipfade. Klassisches Skript
// (kein type="module"), damit es auch per Doppelklick lädt (siehe <script src="social-video-assets.js">
// vor dem Haupt-<script> in index.html). Siehe docs/social-video-spezifikation.md Abschnitt 3.3.
// window.SOCIAL_VIDEO_ASSET_TREATMENT (S2c-Auftrag B3, dunkle Logos lesbar machen): {relPath: {tier,
// factor?}} NUR für Logos unter der Lesbarkeits-Schwelle (mittlere Luminanz der nicht transparenten
// Bildpunkte) — fehlt ein Schlüssel, bleibt das Bild unverändert. tier "invert" (annähernd einfarbige
// dunkle Logos) hellt per Canvas-Filter invert(1) auf; tier "brighten" (farbige dunkle Logos, z. B.
// Vereinsrot — Invertieren würde den Farbton verfälschen) hellt per brightness(factor) auf, OHNE den
// Farbton zu drehen; tier "silhouette" zeichnet eine einfarbig gebrochen-weiße Form aus der Alpha-Maske
// (socialVideoDrawCommand, Fall 'image'). Siehe Abschlussbericht für die betroffenen Logos je Stufe.
window.SOCIAL_VIDEO_ASSETS={"assets/vfb-ulm-logo-mark.png":"data:image/png;base64,","assets/spatz.svg":"data:image/svg+xml;base64,","assets/teams/breisgau-bandits.png":"data:image/png;base64,","assets/teams/fbc-heidelberg.png":"data:image/png;base64,","assets/teams/floorball-mannheim.png":"data:image/png;base64,","assets/teams/sportvg-feuerbach.png":"data:image/png;base64,","assets/teams/sv-tuebingen-sharks.png":"data:image/png;base64,","assets/teams/tv-schriesheim.png":"data:image/png;base64,","assets/teams/vfb-ulm.png":"data:image/png;base64,"};
window.SOCIAL_VIDEO_ASSET_TREATMENT={"assets/vfb-ulm-logo-mark.png":{"tier":"silhouette"},"assets/teams/breisgau-bandits.png":{"tier":"invert"},"assets/teams/fbc-heidelberg.png":{"tier":"silhouette"},"assets/teams/floorball-mannheim.png":{"tier":"invert"},"assets/teams/tv-schriesheim.png":{"tier":"invert"},"assets/teams/vfb-ulm.png":{"tier":"silhouette"}};
